```
import dataclasses
import json
import os
import re
import random

import numpy as np

import llm


re_board = re.compile(r"(.*?)(```[^\n]*\n\s*(\|[01]\|[01]\|[01]\|[01]\|\s*\n\s*){4}```)", re.S)


llmargs = dict(temperature=0.15, max_tokens=512)
llm.setup(max_retries=2, timeout=10)

@dataclasses.dataclass
class Player:
    name: str
    system_prompt: str


class Board:
    def __init__(self):
        self.tiles = np.zeros((4, 4), dtype=int)

    def is_valid_move(self, new_tiles):
        diff = new_tiles - self.tiles

        if np.any(diff < 0) or not np.any(diff > 0):
            return False

        changed = np.argwhere(diff > 0)
        if np.all(changed[:, 0] == changed[0, 0]):
            cols = changed[:, 1]
            if np.max(cols) - np.min(cols) + 1 == len(cols):
                return True

        if np.all(changed[:, 1] == changed[0, 1]):
            rows = changed[:, 0]
            if np.max(rows) - np.min(rows) + 1 == len(rows):
                return True

        return False

    def make_move(self, new_tiles):
        self.tiles = new_tiles

    def is_filled(self):
        return np.sum(self.tiles) == 16

    def to_text(self):
        return "```\n" + "\n".join("|" + "|".join(str(n) for n in x) + "|" for x in self.tiles) + "\n```"


def extract_move(message):
    res = None
    for m in re.finditer(re_board, message):
        res = m

    if not res:
        return None, None

    tiles = np.array([int(x) for x in re.findall(r'[01]', res.group(2))]).reshape((4, 4))
    comment = res.group(1)
    return tiles, comment


def load_players(dirname):
    res = []

    for fname in os.listdir(dirname):
        with open(os.path.join(dirname, fname), encoding="utf-8") as f:
            res.append(Player(os.path.splitext(fname)[0], f.read()))

    return res


@dataclasses.dataclass
class GameOutcome:
    winner: int = None


def play(a, b):
    board = Board()
    turn = 0
    mistakes = [0, 0]
    mistake_limit = 4
    move_history = []
    comment_history = []

    while not board.is_filled():
        playerno = turn % 2
        player = a if playerno == 0 else b

        commented_moves = [comment + move if i % 2 == playerno else move for i, (move, comment) in enumerate(zip(move_history, comment_history))]

        if playerno == 0:
            history = [player.system_prompt] + commented_moves
        else:
            history = [player.system_prompt + "\n\nYou are going second. The first move by other player is:\n" + commented_moves[0]] + commented_moves[1:]

        move = None
        comment = None

        while move is None:
            if mistakes[playerno] > mistake_limit:
                print(f"{player.name} made too many mistakes")
                return GameOutcome(winner=1 - playerno)

            req = llm.reply(llm.Request(history), **llmargs)
            llm.wait(req)
            if req.exception:
                print(req.exception)
                continue

            move, comment = extract_move(req.answer)

            if move is None:
                print(f"===\nPlayer {player.name} wrote an answer without board:\n{req.answer}\n===\n")
                mistakes[playerno] += 1
                history += [req.answer, "[System error: was unable to find the new board in the reply (or the 4x4 board is malformed). Please, include the new board state exactly as described in game rules.]"]
                continue

            if not board.is_valid_move(move):
                print(f"===\nPlayer {player.name} made a bad move:\n{req.answer}\n===\n")
                history += [req.answer, "[System error: the provided move is invalid.]"]
                mistakes[playerno] += 1
                move = None
                continue

        board.make_move(move)
        move_history.append(board.to_text())
        comment_history.append(comment)
        print(f"Turn {turn}, player {player.name}\n{board.to_text()}\n\n")

        if board.is_filled():
            print(f"{player.name} lost the game.")
            return GameOutcome(winner=1 - playerno)

        turn += 1


def loop():
    if os.path.exists("stats.json"):
        with open("stats.json", encoding="utf8") as file:
            stats = json.load(file)
    else:
        stats = {"players": {}}

    player_stats = stats["players"]

    while True:
        players = load_players('prompts')
        for player in players:
            player_stats.setdefault(player.name, {})
            for other_player in players:
                if player.name != other_player.name:
                    player_stats[player.name].setdefault(other_player.name, [0, 0])

        pairs = sum([[(a, b, sum(player_stats[a.name][b.name])) for b in players if a != b] for a in players], [])
        pairs = sorted(pairs, key=lambda x: x[2])
        pairs = [x for x in pairs if x[2] == pairs[0][2]]
        random.shuffle(pairs)
        p1, p2, total_games = pairs[0]

        outcome = play(p1, p2)

        player_stats[p1.name][p2.name][outcome.winner] += 1
        player_stats[p2.name][p1.name][1-outcome.winner] += 1

        with open("stats.json", "w", encoding="utf8") as file:
            stats["stats"] = {p.name: f"{sum(w for op, (w, l) in player_stats[p.name].items())} wins out of {sum(w+l for op, (w, l) in player_stats[p.name].items())} games" for p in players}

            json.dump(stats, file, indent=4, ensure_ascii=False)


loop()
```

interpret.c is meant to implement a bytecode interpreter for a custom bytecode made for prolog. However, it has a bug when dealing with and. Basically, it needs to store the variable vars and call (and maybe other variables) on the continuation stack to restore these values. Also, it stores some information on stack that is freed upon backtracking. Memory leaks are possible. test.S contains a program that doesn't work as exected and test.pl is the program it was compiled from. Step through the bytecode to see where it went wrong. Then, think through the problem step by step to find what information to push to the continuation stack and backtracking stack to work and avoid memory leaks. interpret.c: #include <stdlib.h>
/* #include <string.h> */
/* #include <stdio.h> */

/* #include "interpret.h" */

#include "types.h"
/* #include "symbols.h" */

/**** Symbols ****/
struct SymbolTableEntry {
  intptr_t arity;
  char *name;
};
extern struct SymbolTableEntry *symbol_table;

int functor_arity(symbol s) {
  return symbol_table[(s-1)/2].arity;
}

/**** Machine definition ****/
/* The program counter */
term pc = NULL;

/* The program stack */
List *stack = NULL;

/* Stack of success continuations */
List *scont = NULL;

/* The current call */
term call = NULL;

/* The current matching vars */
term* vars = NULL;

/* Whether the last call succeeded */
char status = 1;

enum Operation {
  /* push a value */
  PUSH = 11,
  /* push a delimiter */
  DELINEATE = 13,
  /* push the current environemnt */
  RECORD = 15,
  /* undo bindings if the last action was a failure */
  UNDO = 17,
  /* backtrack if the last action was a failure */
  BACKTRACK = 19,
  /* branch if the last action was a failure */
  BRANCH = 21,
  /* go to the address and push the next instruction to the
   *  continuation stack */
  CALL = 23,
  /* go to the address */
  JUMP = 25,
  /* return to the continuation at the top of the stack */
  RET = 27,
  /* match a magmoid and store the bindings */
  MATCH_CALL = 29
};

/**** Helpers ****/
#define IS_TERM(T) *(T) % 2
#define IS_VAR(T) *(T) % 2 == 0
#define IS_MAG(M) IS_TERM(M) && (M) >> 63
#define MAG_VARS(M) *(M) >> 1 & 0x7fff
#define MAG_TERMS(M) *(M) >> 16 & 0x7fffffffff

/* Add an element to the stack */
void push(void *i) {
  List *this = malloc(sizeof(List));
  this->item = i;
  this->next = stack;
  stack = this;
}

/* Remove and return the element at the top of the stack */
void *pop(void) {
  if (stack) {
    void *i = stack->item;
    List *old_stack = stack;
    stack = stack->next;
    free(old_stack);
    return i;
  }
  return NULL;
}

/* Undo bindings on the stack until the last choicepoint
 * 
 * Side Effects: removes all bindings and the NULL marker
 *  on the stack
 */
void undo_bindings(void) {
  for (term addr = pop(); addr; addr = pop()) {
    *addr = (symbol)NULL;
  }
}

/* Find the representative of a term
 *
 * Note: unlike some Prolog implementations that use a
 *  self-pointer to represent an unbound variable, we
 *  use a null-pointer
 */
term rep(term t) {
  while (*t && IS_VAR(t)) {
    t = (term)*t;
  }
  return t;
}

/**** Matching and copying ****/

/* Copies template with the variables requested
 *
 * Preconditions: template one element of a magmoid
 */
term copy_template(term template,
                   term *vars) {
  term copy;
  if (IS_TERM(template)) {
    int arity = functor_arity(*template);
    copy = malloc(sizeof(symbol)*(arity+1));
    copy[0] = *template;
    for (int i = 1; i <= arity; i++) {
      copy[i] =
	(symbol)copy_template((term)*(template+i), vars);
    }
  } else {
    copy = malloc(sizeof(symbol));
    *copy = (symbol)(vars+*template/2);
  }
  return copy;
}

/* Unify arbitrary terms a and b
 *
 * Side effects: modifies variables a and b so they are
 *  equal, adds to stack
 */
int unify(term a, term b) {
  a = rep(a);
  b = rep(b);
  if (*a == *b) {
    /* Either a and b have the same functor or are the
       same variable */
    int arity = functor_arity(*a);

    /* Unify children (or do nothing for variables) */
    for (int i = 1; i <= arity; i++) {
      if(!unify(a+i, b+i)) {
	return 0;
      }
    }
    return 1;
  } else if (IS_VAR(a)) {
    push(a);
    *a = (symbol)b;
    return 1;
  } else if (IS_VAR(b)) {
    push(b);
    *b = (symbol)a;
    return 1;
  } 
  /* Failure */
  return 0;
}

/* Match the template with the term, unifying as
 * necessary
 *
 * Preconditions: template is represented as returned by
 *  variable_replace, vars contains enough space for
 *  all variables in template
 * Side effects: modifies t to unify with the template
 */
int match(term template, term t,
	  term *vars) {
  t = rep(t);
  if (IS_TERM(template)) {
    /* template is a term */
    if (IS_TERM(t)) {
      /* t is also a term */
      if (*template == *t) {
	/* same functor, so match children */
	int arity = functor_arity(*t);
	for (int i = 1; i <= arity; i++) {
	  if (!match((term)*(template+i),
		     (term)*(t+i),
		     vars)) {
	    return 0;
	  }
	}
	return 1;
      } else {
	/* functor is different, so this is a failure */
	return 0;
      }
    } else {
      /* copy the template into t */
      push(t);
      *t = (symbol)copy_template(template, vars);
      return 1;
    }
  } else {
    term *var = vars+*template/2;
    if (*var) {
      /* the variable is set already, so unify */
      return unify(*var, t);
    } else {
      /* set the variable */
      *var = t;
      return 1;
    }
  }
}

/**** Machine loop ****/
int execute(term entrypoint, symbol main_symbol) {
  pc = entrypoint;
  call = &main_symbol;
  while (1) {
    switch (*pc) {
    case PUSH:
      push(pc+1);
      pc += 2;
      break;
    case DELINEATE:
      push(NULL);
      pc++;
      break;
    case RECORD:
      if (status) {
        push(vars);
        push(scont);
        push(pc+1);
        push(call);
      }
      pc++;
      break;
    case UNDO:
      if (!status) {
        undo_bindings();
      }
      pc++;
      break;
    case BACKTRACK:
      if (!status) {
        if (!stack) {
          return 0;
        }
        while (!(call = pop())) {
          undo_bindings();
        }
        pc = pop();
        scont = pop();
        term *vars = pop();
        free(vars);
      } else {
        pc++;
      }
      break;
    case BRANCH:
      if (!status) {
        pc = (term)*(pc+1);
      } else {
        pc += 2;
      }
      break;
    case CALL:
      {
        List *this = malloc(sizeof(List));
        this->item = pc+3;
        this->next = scont;
        scont = this;
      }
      /* continue */
    case JUMP:
      call = copy_template((term)*(pc+1), vars);
      pc = (term)*(pc+2);
      break;
    case RET:
      status = 1;
      if (!scont) {
        return 1;
      }
      pc = scont->item;
      List *old = scont;
      scont = scont->next;
      free(old);
      break;
    case MATCH_CALL:
      vars = malloc(sizeof(symbol)*MAG_VARS(pc+1));
      status = match(*((term *)*(pc+1)+1), call, vars);
      pc += 2;
      break;
    /* case MATCH: */
    }
  }
}

