The layout thrashing in your code primarily occurs in the `checkBottom()` function. Here's what's happening:

1. You're reading `offsetHeight` to check if at bottom
2. Then immediately writing to `lock.style.visibility`
3. This forces a reflow between the read and write operations

To fix this, batch your DOM reads and writes:

```javascript
export function checkBottom() {
	if (!page.thread) {
		atBottom = false
		return
	}

	// Batch all reads first
	const previous = atBottom;
	const newAtBottom = isAtBottom()
	const lock = document.getElementById("lock")

	// Then batch all writes
	atBottom = newAtBottom
	if (lock) {
		lock.style.visibility = atBottom ? "visible" : "hidden"
	}
	if (!previous && atBottom) {
		lightenThread();
	}
}
```

Additionally, since `checkBottom()` is called on every scroll event, consider:

1. **Throttling the scroll handler** to reduce the frequency of checks:
```javascript
let scrollTimeout;
document.addEventListener("scroll", () => {
	if (!scrollTimeout) {
		scrollTimeout = requestAnimationFrame(() => {
			scrolled = !isAtBottom()
			locked = !scrolled;
			checkBottom();
			scrollTimeout = null;
		});
	}
}, { passive: true })
```

2. **Using CSS instead of JavaScript** for the lock visibility:
```css
#lock {
	visibility: hidden;
}
body.at-bottom #lock {
	visibility: visible;
}
```

Then toggle a class on the body instead:
```javascript
document.body.classList.toggle('at-bottom', atBottom);
```

This approach eliminates the style calculation from your JavaScript entirely, reducing reflows.

In Windows, you can temporarily redirect stderr during a DLL load and then restore it afterward. Here's how to do it:

```cpp
#include <windows.h>
#include <io.h>
#include <fcntl.h>
#include <stdio.h>

HMODULE LoadDllWithRedirectedStderr(const char* dllPath) {
    // Save the current stderr
    int stderr_backup = _dup(_fileno(stderr));

    // Create a null device or file to redirect to
    FILE* nullFile = fopen("nul", "w");  // or use a real file path
    if (!nullFile) {
        return NULL;
    }

    // Redirect stderr to the null device
    _dup2(_fileno(nullFile), _fileno(stderr));

    // Load the DLL
    HMODULE hModule = LoadLibrary(dllPath);

    // Restore the original stderr
    _dup2(stderr_backup, _fileno(stderr));

    // Clean up
    _close(stderr_backup);
    fclose(nullFile);

    return hModule;
}
```

For a more robust approach that handles edge cases better:

```cpp
class StderrRedirector {
private:
    int original_stderr;
    FILE* redirect_file;
    bool redirected;

public:
    StderrRedirector() : original_stderr(-1), redirect_file(nullptr), redirected(false) {}

    bool Redirect(const char* target = "nul") {
        if (redirected) return false;

        // Duplicate current stderr
        original_stderr = _dup(_fileno(stderr));
        if (original_stderr == -1) return false;

        // Open target file/device
        redirect_file = fopen(target, "w");
        if (!redirect_file) {
            _close(original_stderr);
            return false;
        }

        // Redirect stderr
        if (_dup2(_fileno(redirect_file), _fileno(stderr)) == -1) {
            fclose(redirect_file);
            _close(original_stderr);
            return false;
        }

        redirected = true;
        return true;
    }

    void Restore() {
        if (!redirected) return;

        // Restore original stderr
        _dup2(original_stderr, _fileno(stderr));

        // Clean up
        if (redirect_file) fclose(redirect_file);
        if (original_stderr != -1) _close(original_stderr);

        redirected = false;
    }

    ~StderrRedirector() {
        Restore();
    }
};

// Usage:
HMODULE LoadDllSilently(const char* dllPath) {
    StderrRedirector redirector;
    redirector.Redirect();  // or Redirect("error_log.txt") to save errors

    HMODULE hModule = LoadLibrary(dllPath);

    redirector.Restore();  // Automatically restored even if exception occurs
    return hModule;
}
```

If you need to capture the stderr output instead of discarding it:

```cpp
HMODULE LoadDllAndCaptureStderr(const char* dllPath, std::string& stderrOutput) {
    // Create a temporary file
    char tempPath[MAX_PATH];
    char tempFile[MAX_PATH];
    GetTempPath(MAX_PATH, tempPath);
    GetTempFileName(tempPath, "err", 0, tempFile);

    StderrRedirector redirector;
    redirector.Redirect(tempFile);

    HMODULE hModule = LoadLibrary(dllPath);

    redirector.Restore();

    // Read the captured output
    std::ifstream file(tempFile);
    std::stringstream buffer;
    buffer << file.rdbuf();
    stderrOutput = buffer.str();
    file.close();

    // Delete temp file
    DeleteFile(tempFile);

    return hModule;
}
```

This approach ensures that only the DLL loading process has its stderr redirected, while your main application's stderr remains unchanged before and after the DLL load.

