要让每个 Subscriber 并行执行 `ping_host`，你需要修改 `EventBus.publish` 方法，使用 `asyncio.create_task()` 或 `asyncio.gather()` 来并发执行所有回调。这里有两种实现方式：

## 方式一：使用 asyncio.create_task（火后即忘）

```python
from loguru import logger
import asyncio

class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_type, callback):
        if event_type not in self._subscribers:
            self._subscribers[event_type] = []
        self._subscribers[event_type].append(callback)

    def unsubscribe(self, event_type, callback):
        if event_type in self._subscribers:
            try:
                self._subscribers[event_type].remove(callback)
            except ValueError:
                logger.warning(f"Callback not subscribed for event {event_type}")

    async def publish(self, event_type, *args, **kwargs):
        if event_type in self._subscribers:
            # 创建所有回调的任务，让它们并行执行
            tasks = []
            for callback in self._subscribers[event_type]:
                task = asyncio.create_task(callback(event_type, *args, **kwargs))
                tasks.append(task)

            # 等待所有任务完成
            await asyncio.gather(*tasks, return_exceptions=True)
```

## 方式二：使用 asyncio.gather（推荐）

```python
from loguru import logger
import asyncio

class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_type, callback):
        if event_type not in self._subscribers:
            self._subscribers[event_type] = []
        self._subscribers[event_type].append(callback)

    def unsubscribe(self, event_type, callback):
        if event_type in self._subscribers:
            try:
                self._subscribers[event_type].remove(callback)
            except ValueError:
                logger.warning(f"Callback not subscribed for event {event_type}")

    async def publish(self, event_type, *args, **kwargs):
        if event_type in self._subscribers:
            # 使用 gather 并行执行所有回调
            await asyncio.gather(
                *[callback(event_type, *args, **kwargs) for callback in self._subscribers[event_type]],
                return_exceptions=True  # 防止一个回调的异常影响其他回调
            )
```

## 完整示例（包含模拟的 ping_host）

```python
from loguru import logger
import asyncio
import random

# 模拟的 ping_host 函数
async def ping_host(host):
    delay = random.uniform(1, 3)  # 模拟不同的网络延迟
    logger.info(f"Starting ping to {host}...")
    await asyncio.sleep(delay)
    logger.info(f"Ping to {host} completed in {delay:.2f} seconds")
    return f"Ping result for {host}"

class EventBus:
    def __init__(self):
        self._subscribers = {}

    def subscribe(self, event_type, callback):
        if event_type not in self._subscribers:
            self._subscribers[event_type] = []
        self._subscribers[event_type].append(callback)

    def unsubscribe(self, event_type, callback):
        if event_type in self._subscribers:
            try:
                self._subscribers[event_type].remove(callback)
            except ValueError:
                logger.warning(f"Callback not subscribed for event {event_type}")

    async def publish(self, event_type, *args, **kwargs):
        if event_type in self._subscribers:
            # 使用 gather 并行执行所有回调
            results = await asyncio.gather(
                *[callback(event_type, *args, **kwargs) for callback in self._subscribers[event_type]],
                return_exceptions=True
            )

            # 检查是否有异常
            for i, result in enumerate(results):
                if isinstance(result, Exception):
                    logger.error(f"Error in subscriber {i}: {result}")

class Subscriber:
    def __init__(self, name):
        self.name = name

    async def handle_event(self, event_type, data):
        logger.info(f"Subscriber {self.name} received event '{event_type}' with data: {data}")

        match event_type:
            case "power_on":
                logger.info(f"{self.name}: Handling 'power_on' event.")
            case "power_off":
                logger.info(f"{self.name}: Handling 'power_off' event.")
            case "power_restart":
                logger.info(f"{self.name}: Handling 'power_restart' event.")
                await ping_host(f"{data} (from {self.name})")
            case _:
                logger.warning(f"{self.name}: Unknown event type: {event_type}")

async def main():
    event_bus = EventBus()

    # 创建多个订阅者
    subscribers = [Subscriber(f"Subscriber{i}") for i in range(1, 4)]

    # 订阅事件
    for subscriber in subscribers:
        event_bus.subscribe("power_restart", subscriber.handle_event)

    # 发布事件
    logger.info("Publishing 'power_restart' event...")
    start_time = asyncio.get_event_loop().time()
    await event_bus.publish("power_restart", "www.baidu.com")
    end_time = asyncio.get_event_loop().time()

    logger.info(f"All subscribers completed in {end_time - start_time:.2f} seconds")

if __name__ == '__main__':
    asyncio.run(main())
```

这个实现的关键点：

1. **并行执行**：使用 `asyncio.gather()` 确保所有订阅者的回调函数并行执行
2. **异常处理**：`return_exceptions=True` 参数确保一个订阅者的异常不会影响其他订阅者
3. **性能提升**：如果有多个订阅者，它们会同时执行 `ping_host`，而不是顺序执行

运行这个示例，你会看到所有订阅者几乎同时开始 ping 操作，并且总执行时间接近最慢的那个 ping 操作的时间，而不是所有 ping 操作时间的总和。

