private byte[] GenerateSound(int soundIndex, double durationSeconds, int sampleRate = 44100)
{
    int samples = (int)(sampleRate * durationSeconds);
    byte[] buffer = new byte[samples * 2]; // 16-bit audio
    double amplitude = 0.25 * short.MaxValue * (volumeTrackBar.Value / 100.0); // Volume control

    for (int i = 0; i < samples; i++)
    {
        double t = (double)i / sampleRate;
        short sample = 0;

        switch (soundIndex)
        {
            case 0: // Bip classique 440Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 440 * t));
                break;

            case 1: // Bip aigu 880Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 880 * t));
                break;

            case 2: // Bip grave 220Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 220 * t));
                break;

            case 3: // Double bip alternant entre 440Hz et 880Hz
                double freq = (i / (sampleRate / 4)) % 2 == 0 ? 440 : 880;
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * freq * t));
                break;

            case 4: // Alarme montante (sweep de 200Hz à 800Hz)
                double sweepFreq = 200 + (600 * (t % 3) / 3); // Répète le sweep toutes les 3 secondes
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * sweepFreq * t));
                break;

            case 5: // Alarme sirène (oscillation entre 600Hz et 800Hz)
                double modulation = Math.Sin(2 * Math.PI * 4 * t); // 4Hz modulation
                double sireneFreq = 700 + 100 * modulation;
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * sireneFreq * t));
                break;
        }

        // Fade in/out pour éviter les clics
        if (i < sampleRate / 100) // Fade in sur 10ms
        {
            sample = (short)(sample * i / (sampleRate / 100));
        }
        else if (i > samples - sampleRate / 100) // Fade out sur 10ms
        {
            sample = (short)(sample * (samples - i) / (sampleRate / 100));
        }

        // Convertir en bytes (little-endian)
        buffer[i * 2] = (byte)(sample & 0xFF);
        buffer[i * 2 + 1] = (byte)(sample >> 8);
    }

    // Créer le fichier WAV complet
    using (MemoryStream ms = new MemoryStream())
    {
        BinaryWriter writer = new BinaryWriter(ms);

        // RIFF header
        writer.Write("RIFF".ToCharArray());
        writer.Write(36 + buffer.Length);
        writer.Write("WAVE".ToCharArray());

        // fmt chunk
        writer.Write("fmt ".ToCharArray());
        writer.Write(16); // Chunk size
        writer.Write((short)1); // PCM
        writer.Write((short)1); // Mono
        writer.Write(sampleRate);
        writer.Write(sampleRate * 2); // Byte rate
        writer.Write((short)2); // Block align
        writer.Write((short)16); // Bits per sample

        // data chunk
        writer.Write("data".ToCharArray());
        writer.Write(buffer.Length);
        writer.Write(buffer);

        return ms.ToArray();
    }
}

private void QuickButton_Click(object sender, EventArgs e)
{
    Button btn = sender as Button;
    if (btn != null)
    {
        SetTimeAndStart((int)btn.Tag);
    }
}

private void SetButton_Click(object sender, EventArgs e)
{
    int totalSeconds = (int)hoursInput.Value * 3600 + (int)minutesInput.Value * 60 + (int)secondsInput.Value;
    SetTimeAndStart(totalSeconds);
}

private void SetTimeAndStart(int totalSeconds)
{
    if (totalSeconds <= 0)
    {
        MessageBox.Show("Veuillez entrer un temps positif.", "Temps invalide", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        return;
    }
    StopAndResetTimer();
    remainingSeconds = totalSeconds;
    UpdateTimeDisplay();
    StartTimer();
}

private void StartStopButton_Click(object sender, EventArgs e)
{
    if (isTimerRunning)
    {
        StopTimer();
    }
    else
    {
        if (remainingSeconds == 0)
        {
            int totalSeconds = (int)hoursInput.Value * 3600 + (int)minutesInput.Value * 60 + (int)secondsInput.Value;
            if (totalSeconds <= 0)
            {
                MessageBox.Show("Veuillez définir un temps avant de démarrer.", "Info", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            remainingSeconds = totalSeconds;
            UpdateTimeDisplay();
        }
        StartTimer();
    }
}

private void StartTimer()
{
    if (remainingSeconds > 0 && !isTimerRunning)
    {
        isTimerRunning = true;
        countdownTimer.Start();
        startStopButton.Text = "Arrêter";
        startStopButton.BackColor = Color.LightCoral;
    }
}

private void StopTimer()
{
    isTimerRunning = false;
    countdownTimer.Stop();
    startStopButton.Text = "Démarrer";
    startStopButton.BackColor = Color.LightGreen;
    alarmPlayer.Stop();
}

private void StopAndResetTimer()
{
    StopTimer();
    remainingSeconds = 0;
    UpdateTimeDisplay();
    timeLabel.ForeColor = Color.DarkBlue;
}

private void CountdownTimer_Tick(object sender, EventArgs e)
{
    if (remainingSeconds > 0)
    {
        remainingSeconds--;
        UpdateTimeDisplay();

        // Changer la couleur quand il reste peu de temps
        if (remainingSeconds <= 10)
        {
            timeLabel.ForeColor = Color.Red;
        }
        else if (remainingSeconds <= 30)
        {
            timeLabel.ForeColor = Color.Orange;
        }
    }
    else
    {
        StopTimer();
        UpdateTimeDisplay();
        PlayAlarm();

        // Flash de la fenêtre
        this.WindowState = FormWindowState.Normal;
        this.Activate();
        this.BringToFront();

        MessageBox.Show("Temps écoulé !", "Cook Timer", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }
}

private void UpdateTimeDisplay()
{
    TimeSpan ts = TimeSpan.FromSeconds(remainingSeconds);
    timeLabel.Text = string.Format("{0:D2}:{1:D2}:{2:D2}", ts.Hours, ts.Minutes, ts.Seconds);
}

private void PlayAlarm()
{
    try
    {
        int selectedSound = soundComboBox.SelectedIndex;
        if (selectedSound >= 0 && selectedSound < soundNames.Length)
        {
            // Générer un son de 10 secondes qui se répète en boucle
            byte[] soundBytes = GenerateSound(selectedSound, 10.0);
            using (MemoryStream ms = new MemoryStream(soundBytes))
            {
                alarmPlayer.Stream = ms;
                alarmPlayer.PlayLooping();
            }
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Erreur lecture son: " + ex.Message);
    }
}

private void PlaySound(double duration)
{
    try
    {
        int selectedSound = soundComboBox.SelectedIndex;
        if (selectedSound >= 0 && selectedSound < soundNames.Length)
        {
            byte[] soundBytes = GenerateSound(selectedSound, duration);
            using (MemoryStream ms = new MemoryStream(soundBytes))
            {
                alarmPlayer.Stream = ms;
                alarmPlayer.Play();
            }
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Erreur lecture son: " + ex.Message);
    }
}

// --- Tray Icon Logic ---
private NotifyIcon trayIcon;
private ContextMenuStrip trayMenu;

private void SetupTrayIcon()
{
    trayMenu = new ContextMenuStrip();
    trayMenu.Items.Add("Restaurer", null, OnRestoreFromTray);
    trayMenu.Items.Add("Quitter", null, OnQuitFromTray);

    trayIcon = new NotifyIcon()
    {
        Icon = SystemIcons.Application,
        ContextMenuStrip = trayMenu,
        Visible = false,
        Text = "Cook Timer"
    };
    trayIcon.DoubleClick += OnRestoreFromTray;

    try
    {
        this.Icon = new Icon("app_icon.ico");
        trayIcon.Icon = new Icon("app_icon.ico");
    }
    catch { /* Gérer si l'icône n'est pas trouvée */ }
}

private void CookTimerForm_Resize(object sender, EventArgs e)
{
    if (this.WindowState == FormWindowState.Minimized)
    {
        if (trayIcon == null) SetupTrayIcon();
        trayIcon.Visible = true;
        this.ShowInTaskbar = false;
    }
}

private void OnRestoreFromTray(object sender, EventArgs e)
{
    this.WindowState = FormWindowState.Normal;
    this.ShowInTaskbar = true;
    if (trayIcon != null) trayIcon.Visible = false;
    this.Activate();
}

private void OnQuitFromTray(object sender, EventArgs e)
{
    Application.Exit();
}

protected override void OnFormClosing(FormClosingEventArgs e)
{
    if (trayIcon != null)
    {
        trayIcon.Visible = false;
        trayIcon.Dispose();
    }
    base.OnFormClosing(e);
}

[STAThread]
public static void Main()
{
    Application.EnableVisualStyles();
    Application.SetCompatibleTextRenderingDefault(false);
    Application.Run(new CookTimerForm());
}
}

LLM_output:
Pour que les bips s'arrêtent lorsque vous cliquez sur "OK" sur la fenêtre d'alerte "Temps écoulé !", vous devez modifier la méthode `CountdownTimer_Tick`.

Actuellement, le `StopTimer()` (qui inclut `alarmPlayer.Stop()`) est appelé *avant* que l'alarme ne commence à jouer en boucle (`PlayAlarm()`). Ensuite, l'alarme est lancée et la `MessageBox` apparaît, mais l'alarme continue de jouer en arrière-plan.

Il faut que le `StopAndResetTimer()` (qui lui-même appelle `StopTimer()` et réinitialise tout) soit appelé *après* la `MessageBox.Show()`.

Voici la modification à apporter dans la méthode `CountdownTimer_Tick` :

```csharp
private void CountdownTimer_Tick(object sender, EventArgs e)
{
    if (remainingSeconds > 0)
    {
        remainingSeconds--;
        UpdateTimeDisplay();

        // Changer la couleur quand il reste peu de temps
        if (remainingSeconds <= 10)
        {
            timeLabel.ForeColor = Color.Red;
        }
        else if (remainingSeconds <= 30)
        {
            timeLabel.ForeColor = Color.Orange;
        }
    }
    else // Le temps est écoulé
    {
        // 1. Arrêter le minuteur de compte à rebours
        countdownTimer.Stop();
        isTimerRunning = false; // Mettre à jour l'état
        startStopButton.Text = "Démarrer"; // Réinitialiser le texte du bouton
        startStopButton.BackColor = Color.LightGreen; // Réinitialiser la couleur du bouton

        UpdateTimeDisplay(); // S'assurer que l'affichage est à 00:00:00

        PlayAlarm(); // Déclencher l'alarme (qui joue en boucle)

        // Flash de la fenêtre
        this.WindowState = FormWindowState.Normal;
        this.Activate();
        this.BringToFront();

        // Afficher la boîte de dialogue. L'exécution du code s'interrompt ici
        // jusqu'à ce que l'utilisateur clique sur "OK".
        MessageBox.Show("Temps écoulé !", "Cook Timer", MessageBoxButtons.OK, MessageBoxIcon.Information);

        // 2. Une fois que l'utilisateur a cliqué sur "OK", arrêter l'alarme
        // et réinitialiser complètement l'état du minuteur.
        StopAndResetTimer(); // Cette méthode appelle alarmPlayer.Stop() et réinitialise l'affichage et la couleur.
    }
}
```

**Explication de la modification :**

1.  **Avant la modification :** Votre code appelait `StopTimer()` *avant* `PlayAlarm()`. Cela arrêtait bien le minuteur du compte à rebours, mais ensuite `PlayAlarm()` lançait un son en boucle qui n'était pas arrêté par la suite dans ce bloc `else`.
2.  **Après la modification :**
    *   Nous arrêtons d'abord le `countdownTimer` et mettons à jour l'état du bouton (ce qui est logique car le temps est écoulé).
    *   Ensuite, nous appelons `PlayAlarm()` pour que le son commence à jouer en boucle.
    *   Puis, la `MessageBox.Show()` est affichée. C'est une fonction *bloquante*, ce qui signifie que le reste du code dans ce bloc `else` ne sera pas exécuté tant que l'utilisateur n'aura pas cliqué sur "OK".
    *   Dès que l'utilisateur clique sur "OK", l'exécution reprend, et `StopAndResetTimer()` est appelé. Cette méthode contient `alarmPlayer.Stop()` ce qui arrête le son immédiatement, et elle réinitialise également le temps affiché et la couleur du texte à leur état initial.

C'est l'endroit parfait pour placer l'arrêt de l'alarme car c'est le moment précis où l'utilisateur interagit avec l'application pour accuser réception de l'alerte.

Okay, this is a fun one! Here's a JavaScript snippet you can paste directly into your browser's console (F12 or Ctrl+Shift+I).

This code will:
*   Create small, semi-transparent dots at your mouse cursor's position.
*   Make these dots fade out and disappear after a short time.
*   Randomize the size and color slightly for a more dynamic effect.
*   Provide a function to easily stop the trail.

---

**Instructions:**

1.  Open your browser's developer console (usually by pressing `F12` or `Ctrl+Shift+I`).
2.  Go to the "Console" tab.
3.  Copy the entire code block below.
4.  Paste it into the console and press `Enter`.
5.  Move your mouse around to see the trail!

---

```javascript
(function() {
    // --- Configuration ---
    const TRAIL_OPTIONS = {
        dotMinSize: 5,        // Minimum size of a dot in pixels
        dotMaxSize: 15,       // Maximum size of a dot in pixels
        fadeDuration: 1000,   // How long dots last in milliseconds
        creationInterval: 20, // Minimum time between dot creations in milliseconds
        maxDots: 300          // Maximum number of dots to keep in the DOM
    };

    let lastCreationTime = 0;
    let trailDots = [];
    let trailHandler = null; // To store the mousemove handler for removal

    // --- Helper function to create a random color ---
    function getRandomColor() {
        const hue = Math.floor(Math.random() * 360); // 0-360 for full spectrum
        const saturation = Math.floor(Math.random() * 30) + 70; // 70-100% saturation
        const lightness = Math.floor(Math.random() * 20) + 60; // 60-80% lightness
        return `hsla(${hue}, ${saturation}%, ${lightness}%, 0.7)`; // 0.7 opacity
    }

    // --- Function to create and manage a single dot ---
    function createTrailDot(e) {
        const currentTime = Date.now();
        if (currentTime - lastCreationTime < TRAIL_OPTIONS.creationInterval) {
            return; // Too soon since the last dot
        }
        lastCreationTime = currentTime;

        const dot = document.createElement('div');
        const dotSize = Math.floor(Math.random() * (TRAIL_OPTIONS.dotMaxSize - TRAIL_OPTIONS.dotMinSize + 1)) + TRAIL_OPTIONS.dotMinSize;

        // Apply initial styles
        Object.assign(dot.style, {
            position: 'absolute',
            left: `${e.clientX - dotSize / 2}px`, // Center the dot on the cursor
            top: `${e.clientY - dotSize / 2}px`,   // Center the dot on the cursor
            width: `${dotSize}px`,
            height: `${dotSize}px`,
            backgroundColor: getRandomColor(),
            borderRadius: '50%',
            pointerEvents: 'none', // Crucial: allows clicks/interactions with elements beneath
            opacity: '1',
            zIndex: '99999', // Ensure it's on top of most page content
            transition: `opacity ${TRAIL_OPTIONS.fadeDuration}ms ease-out, transform ${TRAIL_OPTIONS.fadeDuration}ms ease-out`
        });

        // Add to body
        document.body.appendChild(dot);
        trailDots.push(dot);

        // Trigger fade after a tiny delay to ensure transition works
        // (Initial opacity needs to be rendered before it can transition to 0)
        setTimeout(() => {
            dot.style.opacity = '0';
            dot.style.transform = 'scale(0.5)'; // Shrink slightly as it fades
        }, 10);

        // Remove from DOM after fade duration
        setTimeout(() => {
            if (dot.parentNode) { // Check if it's still in the DOM
                dot.remove();
                // Remove from our tracking array
                const index = trailDots.indexOf(dot);
                if (index > -1) {
                    trailDots.splice(index, 1);
                }
            }
        }, TRAIL_OPTIONS.fadeDuration + 50); // Give a little extra time for transition completion

        // Clean up old dots if we exceed the max
        while (trailDots.length > TRAIL_OPTIONS.maxDots) {
            const oldestDot = trailDots.shift(); // Get and remove the oldest dot
            if (oldestDot.parentNode) {
                oldestDot.remove();
            }
        }
    }

    // --- Start the trail ---
    function startTrail() {
        if (trailHandler) {
            console.warn('Cursor trail is already running.');
            return;
        }
        trailHandler = createTrailDot;
        document.addEventListener('mousemove', trailHandler);
        console.log('Cursor trail started! ✨');
        console.log('To stop it, type: _stopCursorTrail() in the console.');
    }

    // --- Stop and clean up the trail ---
    function stopTrail() {
        if (!trailHandler) {
            console.warn('Cursor trail is not running.');
            return;
        }
        document.removeEventListener('mousemove', trailHandler);
        trailHandler = null;

        // Remove all existing dots
        trailDots.forEach(dot => {
            if (dot.parentNode) {
                dot.remove();
            }
        });
        trailDots = [];
        console.log('Cursor trail stopped and cleaned up. 👋');
    }

    // --- Expose the stop function globally for easy access ---
    window._stopCursorTrail = stopTrail;

    // --- Start it automatically when the script runs ---
    startTrail();

})();
```

