      activeComponent.value = nextBlock;
    } else if (nextBlock?.block_type === "section") {
      activeSection.value = nextBlock;
    } else if (nextBlock?.block_type === "sub-section") {
      if (activeSection.value) {
        activeSection.value.sub_sections[nextBlock.id] = nextBlock;
      }
    }

    await nextTick();
    resume();
  };

  const clearHistory = () => {
    undoStack.value = [];
    redoStack.value = [];
  };

  onMounted(() => {
    clearHistory();
  });

  return { undoActiveBlock, redoActiveBlock, clearHistory };
}
```

---

### ✅ Benefits of Using `pushWithLimit`

- Prevents memory overgrowth in history
- Makes the undo/redo stacks predictable
- Keeps code DRY and easy to maintain

---

If you want to scale it further or apply to any reactive arrays tied to Vue components/composables, consider wrapping `pushWithLimit` in a composable-friendly reactive utility!

