Here’s the updated Swift function reflecting your logic:

```swift
func addQueryItemIfMissing(name: String, value: String?) {
    let finalValue = (value?.isEmpty == false) ? value : AnalyticsConstant.noValue

    if name == AnalyticsConstant.cookieStichingParams.source {
        if let index = innerQueryItems.firstIndex(where: { $0.name == name }) {
            let existingValue = innerQueryItems[index].value ?? UtilStrings.empty
            if [UtilStrings.empty, "mobile_app"].contains(existingValue) {
                // Replace with default value of source=cardplus
                innerQueryItems[index] = URLQueryItem(name: name, value: finalValue)
            }
        } else {
            // "source" not present at all – add it
            innerQueryItems.append(URLQueryItem(name: name, value: finalValue))
        }
    } else if name == AnalyticsConstant.cookieStichingParams.cid && finalValue == AnalyticsConstant.noValue {

        // Check current 'source' value
        if let sourceIndex = innerQueryItems.firstIndex(where: { $0.name == AnalyticsConstant.cookieStichingParams.source }) {
            let sourceValue = innerQueryItems[sourceIndex].value ?? UtilStrings.empty

            if sourceValue.contains("cardplus") {
                // Remove existing 'cid' if present
                innerQueryItems.removeAll(where: { $0.name == AnalyticsConstant.cookieStichingParams.cid })

                // Add new cid with default value
                innerQueryItems.append(URLQueryItem(
                    name: name,
                    value: AnalyticsConstant.cookieStichingParams.defaultCIDAppToWeb
                ))
            }
            // If source does NOT contain "cardplus", leave cid as noValue (i.e. do nothing)
        }

    } else {
        // For any other parameter, add it if missing
        if !innerQueryItems.contains(where: { $0.name == name }) {
            innerQueryItems.append(URLQueryItem(name: name, value: finalValue))
        }
    }
}
```

### What's Changed:

- For the `"cid"` key:
  - If `source` contains "cardplus":
    - Remove existing `"cid"` if found.
    - Add it with the default value (`defaultCIDAppToWeb`).
  - If `source` does **not** contain `"cardplus"`, skip adding `"cid"` altogether (even if it was empty).

