  for (let x = 0; x < MAP_WIDTH; x++) {
    row.push({
      elevation: Math.floor(Math.random() * 5), // 0 to 4
      color: `hsl(${Math.random() * 40 + 100}, 50%, ${Math.random() * 20 + 30}%)`
    });
  }
  map.push(row);
}

// Player
const player = {
  x: Math.floor(MAP_WIDTH / 2),
  y: Math.floor(MAP_HEIGHT / 2),
  offsetX: 0,
  offsetY: 0,
  width: 32,
  height: 48,
  color: 'red'
};

// Input
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

// Game loop
function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

// Update
function update() {
  if (keys['ArrowUp']) player.y -= 0.1;
  if (keys['ArrowDown']) player.y += 0.1;
  if (keys['ArrowLeft']) player.x -= 0.1;
  if (keys['ArrowRight']) player.x += 0.1;

  // Clamp player position
  player.x = Math.max(0, Math.min(MAP_WIDTH - 1, player.x));
  player.y = Math.max(0, Math.min(MAP_HEIGHT - 1, player.y));
}

// Draw
function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Calculate camera offset
  const centerX = VIEWPORT_WIDTH / 2;
  const centerY = VIEWPORT_HEIGHT / 2;
  const playerScreen = isoToScreen(player.x, player.y, getElevation(player.x, player.y));
  const offsetX = centerX - playerScreen.x;
  const offsetY = centerY - playerScreen.y;

  // Draw map
  for (let y = 0; y < MAP_HEIGHT; y++) {
    for (let x = 0; x < MAP_WIDTH; x++) {
      const tile = map[y][x];
      const screen = isoToScreen(x, y, tile.elevation);
      drawTile(screen.x + offsetX, screen.y + offsetY, tile.color, tile.elevation);
    }
  }

  // Draw player
  const playerScreenPos = isoToScreen(player.x, player.y, getElevation(player.x, player.y));
  ctx.fillStyle = player.color;
  const scale = 1 + getElevation(player.x, player.y) * 0.1;
  ctx.save();
  ctx.translate(playerScreenPos.x + offsetX, playerScreenPos.y + offsetY - player.height * scale / 2);
  ctx.scale(scale, scale);
  ctx.fillRect(-player.width/2, -player.height, player.width, player.height);
  ctx.restore();
}

// Helpers
function isoToScreen(x, y, elevation) {
  return {
    x: (x - y) * TILE_WIDTH/2,
    y: (x + y) * TILE_HEIGHT/2 - elevation * 10
  };
}

function drawTile(x, y, color, elevation) {
  ctx.save();
  ctx.translate(x, y);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(TILE_WIDTH/2, TILE_HEIGHT/2);
  ctx.lineTo(0, TILE_HEIGHT);
  ctx.lineTo(-TILE_WIDTH/2, TILE_HEIGHT/2);
  ctx.closePath();
  ctx.fillStyle = color;
  ctx.fill();
  ctx.restore();
}

function getElevation(x, y) {
  const xi = Math.floor(x);
  const yi = Math.floor(y);
  if (xi >= 0 && xi < MAP_WIDTH && yi >= 0 && yi < MAP_HEIGHT) {
    return map[yi][xi].elevation;
  }
  return 0;
}

// Start
gameLoop();
</script>
</body>
</html>
```

